import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Ανεξάρτητος σταθμός σχεδιασμού","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/independent-design.md","filePath":"el/websites/independent-design.md"}'),n={name:"el/websites/independent-design.md"};function s(d,e,l,r,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ανεξαρτητος-σταθμος-σχεδιασμου" tabindex="-1">Ανεξάρτητος σταθμός σχεδιασμού <a class="header-anchor" href="#ανεξαρτητος-σταθμος-σχεδιασμου" aria-label="Permalink to &quot;Ανεξάρτητος σταθμός σχεδιασμού&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="σκοπος" tabindex="-1">Σκοπός <a class="header-anchor" href="#σκοπος" aria-label="Permalink to &quot;Σκοπός&quot;">​</a></h2><p>Χρησιμοποιήστε το ανεξάρτητο Theme Studio για σχεδιασμό και ανταλλαγή πακέτων χωρίς πρόσβαση σε επιχειρησιακά δεδομένα. Η διαδικασία αφορά τον σταθμό σχεδιασμού, όχι τον σταθμό τεκμηρίωσης.</p><h2 id="προυποθεσεις-και-διαδικασια" tabindex="-1">Προϋποθέσεις και διαδικασία <a class="header-anchor" href="#προυποθεσεις-και-διαδικασια" aria-label="Permalink to &quot;Προϋποθέσεις και διαδικασία&quot;">​</a></h2><ol><li>Χρησιμοποιήστε εγκεκριμένο φορητό kit από αντίστοιχο κώδικα εφαρμογής. Ο οδηγός αναφοράς περιγράφει <code>npm run export:theme-studio-kit</code> στον σταθμό ανάπτυξης.</li><li>Στον σταθμό σχεδιασμού χρησιμοποιήστε <code>START_THEME_STUDIO.ps1</code> και ανοίξτε <code>http://127.0.0.1:4310</code>. Ακολουθήστε τις οδηγίες της συγκεκριμένης έκδοσης του kit.</li><li>Αντιγράψτε υπάρχον στυλ, ρυθμίστε tokens, διάταξη, μεταφράσεις και εγκεκριμένα αρχεία. Ελέγξτε αντίθεση και συσκευές.</li><li>Χρησιμοποιήστε <strong>Save Local Draft</strong> και εξαγωγή <code>.tbtheme.json</code> ή <code>.tbsite.json</code> για αντίστοιχο προσχέδιο πολλών σελίδων.</li><li>Μεταφέρετε μόνο το επικυρωμένο πακέτο στον υπεύθυνο χειριστή για έλεγχο και εισαγωγή, χωρίς διαπιστευτήρια ή δεδομένα πελατών.</li></ol><h2 id="αποτελεσμα-και-αντιμετωπιση-προβληματων" tabindex="-1">Αποτέλεσμα και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αποτελεσμα-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αποτέλεσμα και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Το ανεξάρτητο kit δεν απαιτεί βάση εφαρμογής ή σύνδεση χειριστή και δεν δημοσιεύει το προϊόν. Αν υπάρχει ασυμβατότητα, επιβεβαιώστε έκδοση με την ομάδα ανάπτυξης και εξαγάγετε ξανά. Μην παρακάμπτετε επικύρωση. Δείτε <a href="./portable-packages.html">φορητά πακέτα</a>.</p>',8)])])}const m=t(n,[["render",s]]);export{_ as __pageData,m as default};
